INSERT OR IGNORE INTO events(id,slug,status,starts_at,ends_at,updated_at,revision,data) VALUES ('687fbd18-57fb-40f3-914c-f3b6042b3708','writers-group','published','2026-10-06T01:00:00.000Z','2026-10-06T03:00:00.000Z','2026-10-01T04:00:00.000Z','1','{"id":"687fbd18-57fb-40f3-914c-f3b6042b3708","slug":"writers-group","status":"published","mode":"walkin","date":"2026-10-05","time":"19:00","endDate":"2026-10-05","endTime":"21:00","startsAt":"2026-10-06T01:00:00.000Z","endsAt":"2026-10-06T03:00:00.000Z","title":"Writers Group","titleEs":"Grupo de Guion","description":"We read short scripts out loud, then talk about what worked, what didn’t, and what the next draft needs. Writers, actors, filmmakers, and anyone who likes a good story are welcome.\n\nYou don’t need to bring a script. Come ready to read, listen, and join the conversation. Free and open to the public.","descriptionEs":"Leemos guiones cortos en voz alta y después hablamos de lo que funcionó, lo que no y lo que necesita el siguiente borrador. Son bienvenidos quienes escriben, actúan, hacen cine o simplemente disfrutan una buena historia.\n\nNo necesitas traer un guion. Ven con ganas de leer, escuchar y participar. Gratis y abierto al público.","details":"Table reads and script feedback","detailsEs":"Lecturas de guion y comentarios","price":"Free admission","priceEs":"Entrada gratuita","image":"/assets/room.webp","imageAlt":"A Dust Wave sign beside a seated skeleton at the studio","imageAltEs":"Un letrero de Dust Wave junto a un esqueleto sentado en el estudio","url":"","infoUrl":"https://dustwave.xyz/writers-group.html#readings","infoUrlEs":"https://dustwave.xyz/es/writers-group.html#readings","infoLabel":"Upcoming readings & script submissions","infoLabelEs":"Próximas lecturas y envío de guiones","updatedAt":"2026-10-01T04:00:00.000Z","revision":1,"repeat":"fortnightly","repeatUntil":"","exceptions":[]}');
